-- Zaal catalog: persistent single-row document with revision history.
CREATE TABLE IF NOT EXISTS catalog (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  revision INTEGER NOT NULL CHECK (revision >= 1),
  data TEXT NOT NULL CHECK (json_valid(data)),
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS catalog_history (
  revision INTEGER PRIMARY KEY,
  data TEXT NOT NULL CHECK (json_valid(data)),
  saved_at TEXT NOT NULL
);

CREATE TRIGGER IF NOT EXISTS catalog_before_update
BEFORE UPDATE ON catalog
FOR EACH ROW
BEGIN
  INSERT OR REPLACE INTO catalog_history (revision, data, saved_at)
  VALUES (OLD.revision, OLD.data, OLD.updated_at);
END;

